previewCss:
.darma-loader-darma-b14-play-pause-morph { --accent: var(--loader-color, #6366f1); --accent-2: var(--loader-secondary-color, #22d3ee); width: var(--loader-size, 84px); height: var(--loader-size, 84px); position: relative; }
.darma-loader-darma-b14-play-pause-morph span { position: absolute; top: 19%; width: 24%; height: 62%; background: linear-gradient(var(--accent), var(--accent-2)); }
.darma-loader-darma-b14-play-pause-morph span:nth-child(1) { left: 26%; animation: darma-loader-darma-b14-play-pause-morph-morph-left calc(var(--loader-speed, 1s) * 2.6) ease-in-out infinite; }
.darma-loader-darma-b14-play-pause-morph span:nth-child(2) { left: 50%; animation: darma-loader-darma-b14-play-pause-morph-morph-right calc(var(--loader-speed, 1s) * 2.6) ease-in-out infinite; }
@keyframes darma-loader-darma-b14-play-pause-morph-morph-left { 0%, 18% { clip-path: polygon(0 0, 100% 24%, 100% 76%, 0 100%); transform: translateX(0); } 46%, 72% { clip-path: polygon(0 0, 100% 0, 100% 100%, 0 100%); transform: translateX(-16%); } 94%, 100% { clip-path: polygon(0 0, 100% 24%, 100% 76%, 0 100%); transform: translateX(0); } }
@keyframes darma-loader-darma-b14-play-pause-morph-morph-right { 0%, 18% { clip-path: polygon(0 24%, 100% 49%, 100% 51%, 0 76%); transform: translateX(0); } 46%, 72% { clip-path: polygon(0 0, 100% 0, 100% 100%, 0 100%); transform: translateX(16%); } 94%, 100% { clip-path: polygon(0 24%, 100% 49%, 100% 51%, 0 76%); transform: translateX(0); } }

